function chargingHops(ranges) {
    function reachable(station) {
        if (station >= ranges.length - 1)
            return true;
        for (let hop = 1; hop <= ranges[station]; hop++)
            if (reachable(station + hop))
                return true;
        return false;
    }
    return reachable(0);
}

function chargingHops(ranges) {
    let farthest = 0;
    for (let i = 0; i <= farthest && i < ranges.length; i++)
        farthest = Math.max(farthest, i + ranges[i]);
    return farthest >= ranges.length - 1;
}
